// Street furniture, signs, markings and parked cars (generated by tools/streets.py).
// Each kind is one instanced mesh built from a few coloured parts; signs and bus stop name
// plates carry their own text textures.
import * as THREE from "three";
import { mergeGeometries } from "three/examples/jsm/utils/BufferGeometryUtils.js";
import { GameMap } from "./map";
import { Culler } from "./cull";

export type Part = [THREE.BufferGeometry, string, number, number, number, number?];   // geometry, colour, x, y, z, rotate about x

/** Merge parts into one geometry with per-vertex colours. Local axes: +x along the street, +z toward it. */
export function model(parts: Part[]): THREE.BufferGeometry {
  const geos = parts.map(([g, col, x, y, z, rx]) => {
    const c = g.clone().toNonIndexed();
    if (rx) c.rotateX(rx);
    c.translate(x, y, z);
    const k = new THREE.Color(col);
    const n = c.attributes.position.count;
    c.setAttribute("color", new THREE.Float32BufferAttribute(new Array(n).fill(0).flatMap(() => [k.r, k.g, k.b]), 3));
    c.deleteAttribute("uv");
    return c;
  });
  return mergeGeometries(geos)!;
}
const box = (w: number, h: number, d: number) => new THREE.BoxGeometry(w, h, d);
const cyl = (r: number, h: number, seg = 8) => new THREE.CylinderGeometry(r, r, h, seg);

const MODELS: Record<string, () => THREE.BufferGeometry> = {
  lamp: () => model([
    [cyl(0.075, 6.4), "#3c4043", 0, 3.2, 0], [box(0.07, 0.07, 1.3), "#3c4043", 0, 6.35, 0.6],
    [box(0.32, 0.1, 0.55), "#3c4043", 0, 6.3, 1.2], [box(0.26, 0.03, 0.46), "#f3efd8", 0, 6.24, 1.2],
  ]),
  pole: () => model([
    [new THREE.CylinderGeometry(0.11, 0.15, 8.2, 7), "#5b4634", 0, 4.1, 0], [box(1.2, 0.1, 0.1), "#4a3a2c", 0, 7.6, 0],
    [cyl(0.05, 0.12), "#d9d9d4", -0.45, 7.7, 0], [cyl(0.05, 0.12), "#d9d9d4", 0.45, 7.7, 0],
  ]),
  wheelie: () => model([
    [box(0.58, 0.95, 0.72), "#ffffff", 0, 0.55, 0], [box(0.62, 0.06, 0.78), "#ffffff", 0, 1.05, 0.02],
    [cyl(0.1, 0.06, 8), "#151515", -0.24, 0.1, -0.36, Math.PI / 2], [cyl(0.1, 0.06, 8), "#151515", 0.24, 0.1, -0.36, Math.PI / 2],
  ]),
  bin: () => model([[cyl(0.24, 0.9, 10), "#2b3a31", 0, 0.45, 0], [cyl(0.26, 0.06, 10), "#1f2a23", 0, 0.92, 0]]),
  postbox: () => model([
    [cyl(0.27, 1.2, 12), "#c4211b", 0, 0.6, 0], [cyl(0.3, 0.1, 12), "#c4211b", 0, 1.25, 0],
    [box(0.24, 0.03, 0.05), "#111111", 0, 1.0, 0.26], [cyl(0.29, 0.12, 12), "#1b1b1b", 0, 0.06, 0],
  ]),
  bollard: () => model([[cyl(0.09, 0.9), "#222426", 0, 0.45, 0], [cyl(0.1, 0.06), "#c9b27a", 0, 0.75, 0]]),
  bench: () => model([
    [box(1.7, 0.06, 0.42), "#8a6a48", 0, 0.46, 0], [box(1.7, 0.36, 0.05), "#8a6a48", 0, 0.78, -0.22],
    [box(0.06, 0.46, 0.42), "#2e3133", -0.75, 0.23, 0], [box(0.06, 0.46, 0.42), "#2e3133", 0.75, 0.23, 0],
  ]),
  info: () => model([
    [box(0.08, 1.4, 0.08), "#2a2d2f", -0.55, 0.7, 0], [box(0.08, 1.4, 0.08), "#2a2d2f", 0.55, 0.7, 0],
    [box(1.3, 0.85, 0.06), "#2f4a3a", 0, 1.45, 0],
  ]),
  car: () => {
    // side profile (x along the car, y up), extruded across its width
    const prof = (pts: number[][], depth: number) => {
      const sh = new THREE.Shape(pts.map(([x, y]) => new THREE.Vector2(x, y)));
      return new THREE.ExtrudeGeometry(sh, { depth, bevelEnabled: false }).translate(0, 0, -depth / 2);
    };
    const body = prof([[-2.05, 0.28], [2.05, 0.28], [2.08, 0.62], [1.95, 0.86], [1.15, 0.98], [-1.7, 1.02], [-2.05, 0.9]], 1.72);
    const cabin = prof([[1.05, 0.98], [0.35, 1.42], [-1.05, 1.44], [-1.62, 1.02]], 1.56);
    const glass = prof([[0.98, 1.0], [0.38, 1.37], [-1.0, 1.39], [-1.52, 1.04]], 1.6);
    return model([
      [body, "#ffffff", 0, 0, 0], [cabin, "#ffffff", 0, 0, 0], [glass, "#20272d", 0, 0, 0],
      [box(0.06, 0.12, 0.5), "#f1f0e6", 2.06, 0.7, 0.55], [box(0.06, 0.12, 0.5), "#f1f0e6", 2.06, 0.7, -0.55],   // headlights
      [box(0.06, 0.12, 0.42), "#a3221b", -2.06, 0.8, 0.6], [box(0.06, 0.12, 0.42), "#a3221b", -2.06, 0.8, -0.6], // tail lights
      [box(4.2, 0.16, 1.76), "#2b2d30", 0, 0.34, 0],                                                            // bumpers and sills
      ...[-1.3, 1.3].flatMap((x) => [-0.8, 0.8].map((z) => [cyl(0.33, 0.24, 12), "#18191b", x, 0.33, z, Math.PI / 2] as Part)),
    ]);
  },
  busflag: () => model([
    [cyl(0.045, 2.9), "#2d3033", 0, 1.45, 0], [box(0.44, 0.5, 0.04), "#f4f4f0", 0, 2.65, 0],
    [cyl(0.15, 0.05, 16), "#c8261e", 0, 2.7, 0.03, Math.PI / 2], [cyl(0.15, 0.05, 16), "#c8261e", 0, 2.7, -0.03, Math.PI / 2],
    [box(0.1, 0.5, 0.25), "#2d3033", 0, 1.5, 0],
  ]),
  shelter: () => model([
    ...[-1.5, 1.5].map((x) => [box(0.08, 2.3, 0.08), "#24402f", x, 1.15, -0.2] as Part),
    ...[-1.5, 1.5].map((x) => [box(0.08, 2.3, 0.08), "#24402f", x, 1.15, -1.3] as Part),
    [box(3.3, 0.1, 1.6), "#2f5a3f", 0, 2.35, -0.75], [box(1.6, 0.05, 0.36), "#24402f", 0, 0.5, -1.1],
  ]),
  shelterglass: () => model([
    [box(3.0, 2.0, 0.03), "#cfe3ea", 0, 1.2, -1.3], [box(0.03, 2.0, 1.0), "#cfe3ea", -1.5, 1.2, -0.75], [box(0.03, 2.0, 1.0), "#cfe3ea", 1.5, 1.2, -0.75],
  ]),
  signposts: () => model([[cyl(0.035, 1.35), "#2b2e31", -0.62, 0.67, 0], [cyl(0.035, 1.35), "#2b2e31", 0.62, 0.67, 0]]),
};

const CAR_PAINT = ["#b8bcc0", "#2c3036", "#e9ebed", "#7a1d1d", "#1f3c66", "#4a4f56", "#8f9499", "#21452f", "#c9b48a", "#a33a1c"];

/** White plate with black lettering, like a modern Bath street sign. */
function plateTexture(text: string, w: number, h: number, sub?: string): THREE.CanvasTexture {
  const c = document.createElement("canvas");
  c.width = w; c.height = h;
  const g = c.getContext("2d")!;
  g.fillStyle = "#f7f6f1"; g.fillRect(0, 0, w, h);
  g.strokeStyle = "#151515"; g.lineWidth = h * 0.06; g.strokeRect(h * 0.08, h * 0.08, w - h * 0.16, h - h * 0.16);
  g.fillStyle = "#151515";
  g.textAlign = "center"; g.textBaseline = "middle";
  let size = h * (sub ? 0.38 : 0.52);
  g.font = `600 ${size}px "Transport", "Helvetica Neue", Arial, sans-serif`;
  while (g.measureText(text).width > w * 0.88 && size > 8) { size -= 2; g.font = `600 ${size}px "Helvetica Neue", Arial, sans-serif`; }
  g.fillText(text, w / 2, sub ? h * 0.4 : h * 0.53);
  if (sub) { g.font = `500 ${h * 0.2}px "Helvetica Neue", Arial, sans-serif`; g.fillText(sub, w / 2, h * 0.75); }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  return t;
}

export function buildFurniture(map: GameMap, scene: THREE.Scene, culler: Culler) {
  const D = map.d, Z0 = map.z0;
  const byKind = new Map<string, (string | number)[][]>();
  for (const f of D.fx ?? []) {
    const k = f[0] as string;
    (byKind.get(k) ?? byKind.set(k, []).get(k)!).push(f);
  }
  const mat = new THREE.MeshLambertMaterial({ vertexColors: true });
  const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), up = new THREE.Vector3(0, 1, 0), one = new THREE.Vector3(1, 1, 1), p = new THREE.Vector3();
  const place = (f: (string | number)[]) => {
    q.setFromAxisAngle(up, f[4] as number);
    return m4.compose(p.set(f[1] as number, (f[3] as number) - Z0, -(f[2] as number)), q, one);
  };
  // one instanced mesh per 250 m square, so distant squares can be skipped
  const instanced = (geo: THREE.BufferGeometry, all: (string | number)[][], material: THREE.Material = mat, colour?: (f: (string | number)[]) => string) => {
    const groups = new Map<string, (string | number)[][]>();
    for (const f of all) {
      const k = `${Math.floor((f[1] as number) / 250)},${Math.floor((f[2] as number) / 250)}`;
      (groups.get(k) ?? groups.set(k, []).get(k)!).push(f);
    }
    for (const items of groups.values()) {
      const m = new THREE.InstancedMesh(geo, material, items.length);
      items.forEach((f, i) => { m.setMatrixAt(i, place(f)); if (colour) m.setColorAt(i, new THREE.Color(colour(f))); });
      m.castShadow = true; m.receiveShadow = true;
      m.computeBoundingSphere();
      scene.add(m);
      culler.add(m, 200);
    }
  };
  for (const kind of ["lamp", "bin", "postbox", "bollard", "bench", "info"]) instanced(MODELS[kind](), byKind.get(kind) ?? []);
  instanced(MODELS.car(), byKind.get("car") ?? [], mat, (f) => CAR_PAINT[(f[5] as number) % CAR_PAINT.length]);
  instanced(MODELS.pole(), byKind.get("pole") ?? []);
  // overhead wires, sagging a little between their ends
  const wpos: number[] = [];
  for (const [x0, y0, z0, x1, y1, z1] of D.wr ?? []) {
    const n = 6, len = Math.hypot(x1 - x0, y1 - y0), sag = Math.min(0.9, len * 0.018);
    for (let k = 0; k < n; k++) {
      const a = k / n, b = (k + 1) / n;
      const P = (t: number) => [x0 + (x1 - x0) * t, z0 + (z1 - z0) * t - Z0 - sag * 4 * t * (1 - t), -(y0 + (y1 - y0) * t)];
      wpos.push(...P(a), ...P(b));
    }
  }
  if (wpos.length) {
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.Float32BufferAttribute(wpos, 3));
    scene.add(new THREE.LineSegments(g, new THREE.LineBasicMaterial({ color: "#1d1f21", transparent: true, opacity: 0.75 })));
  }
  // wheelie bins: black (general waste), green (garden), blue (recycling)
  instanced(MODELS.wheelie(), byKind.get("wheelie") ?? [], mat, (f) => ["#2a2c2e", "#2f5e35", "#2d4f86"][(f[5] as number) % 3]);

  // bus stops: flag, optional shelter, and a name plate
  const stops = byKind.get("bus") ?? [];
  instanced(MODELS.busflag(), stops);
  const sheltered = stops.filter((f) => f[6]);
  instanced(MODELS.shelter(), sheltered);
  instanced(MODELS.shelterglass(), sheltered, new THREE.MeshLambertMaterial({ vertexColors: true, transparent: true, opacity: 0.28, depthWrite: false }));
  const plates = new Map<string, THREE.Material>();
  const plateFor = (text: string, sub?: string) => {
    const key = text + "|" + (sub ?? "");
    let m = plates.get(key);
    if (!m) plates.set(key, (m = new THREE.MeshLambertMaterial({ map: plateTexture(text, sub ? 384 : 512, sub ? 128 : 96, sub) })));
    return m;
  };
  const edge = new THREE.MeshLambertMaterial({ color: "#151515" });
  for (const f of stops) {
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.3, 0.04), [edge, edge, edge, edge, plateFor(f[5] as string, "Bus stop"), plateFor(f[5] as string, "Bus stop")]);
    mesh.applyMatrix4(place(f));
    mesh.position.y += 2.1;
    scene.add(mesh);
    culler.add(mesh, 120);
  }

  // street name signs
  const signs = byKind.get("sign") ?? [];
  instanced(MODELS.signposts(), signs);
  for (const f of signs) {
    const plate = plateFor(f[5] as string);
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(1.4, 0.3, 0.035), [edge, edge, edge, edge, plate, plate]);
    mesh.applyMatrix4(place(f));
    mesh.position.y += 1.2;
    mesh.castShadow = true;
    scene.add(mesh);
    culler.add(mesh, 120);
  }

  // road markings: thin white strips just above the carriageway
  const pos: number[] = [];
  for (const [ax, ay, bx, by, za, zb, kind] of D.mk ?? []) {
    const dx = bx - ax, dy = by - ay, l = Math.hypot(dx, dy) || 1;
    const w = (kind ? 0.15 : 0.1) / 2, nx = -dy / l * w, ny = dx / l * w;
    const ya = map.ground(ax, -ay) + 0.085, yb = map.ground(bx, -by) + 0.085;
    void za; void zb;
    const A = [ax + nx, ya, -(ay + ny)], B = [bx + nx, yb, -(by + ny)], C = [bx - nx, yb, -(by - ny)], Dd = [ax - nx, ya, -(ay - ny)];
    pos.push(...A, ...Dd, ...C, ...A, ...C, ...B);
  }
  if (pos.length) {
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
    g.computeVertexNormals();
    const m = new THREE.Mesh(g, new THREE.MeshLambertMaterial({ color: "#e9e7df", side: THREE.DoubleSide, polygonOffset: true, polygonOffsetFactor: -5, polygonOffsetUnits: -10 }));
    m.receiveShadow = true;
    scene.add(m);
  }
}

// ---- shop signs and landmarks -------------------------------------------------------------
const SIGN_STYLE: Record<string, { bg: string; fg: string; font: string }> = {
  pub: { bg: "#1f3b2d", fg: "#e2c477", font: "Georgia, 'Times New Roman', serif" },
  cafe: { bg: "#5d7461", fg: "#f3ead6", font: "Georgia, serif" },
  shop: { bg: "#1d2b45", fg: "#f4f1ea", font: "'Helvetica Neue', Arial, sans-serif" },
  agent: { bg: "#5a1f2b", fg: "#f4efe6", font: "Georgia, serif" },
  health: { bg: "#f5f5f2", fg: "#1b6e3a", font: "'Helvetica Neue', Arial, sans-serif" },
  civic: { bg: "#202326", fg: "#ece4cf", font: "Georgia, serif" },
};

/** Painted timber fascia: lettering centred on a coloured board with a thin moulding. */
function fasciaTexture(text: string, style: string, w: number, h: number): THREE.CanvasTexture {
  const st = SIGN_STYLE[style] ?? SIGN_STYLE.shop;
  const c = document.createElement("canvas");
  c.width = w; c.height = h;
  const g = c.getContext("2d")!;
  g.fillStyle = st.bg; g.fillRect(0, 0, w, h);
  g.strokeStyle = st.fg; g.globalAlpha = 0.6; g.lineWidth = h * 0.04;
  g.strokeRect(h * 0.1, h * 0.1, w - h * 0.2, h - h * 0.2);
  g.globalAlpha = 1;
  g.fillStyle = st.fg; g.textAlign = "center"; g.textBaseline = "middle";
  let size = h * 0.5;
  g.font = `600 ${size}px ${st.font}`;
  while (g.measureText(text).width > w * 0.86 && size > 10) { size -= 2; g.font = `600 ${size}px ${st.font}`; }
  g.fillText(text, w / 2, h * 0.54);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  return t;
}

/** Shop window: glazing bars over dark glass, with a stall riser below. */
function shopWindowTexture(): THREE.CanvasTexture {
  const c = document.createElement("canvas");
  c.width = 256; c.height = 128;
  const g = c.getContext("2d")!;
  const glass = g.createLinearGradient(0, 0, 256, 128);
  glass.addColorStop(0, "#41505c"); glass.addColorStop(0.5, "#26333d"); glass.addColorStop(1, "#52646f");
  g.fillStyle = glass; g.fillRect(0, 0, 256, 104);
  g.fillStyle = "#e6e0d2";
  g.fillRect(0, 0, 256, 6); g.fillRect(0, 100, 256, 6); g.fillRect(0, 0, 6, 106); g.fillRect(250, 0, 6, 106);
  g.fillRect(84, 0, 4, 104); g.fillRect(168, 0, 4, 104); g.fillRect(0, 30, 256, 3);
  g.fillStyle = "#3b4044"; g.fillRect(0, 106, 256, 22);        // stall riser
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export function buildShops(map: GameMap, scene: THREE.Scene, culler: Culler) {
  const D = map.d, Z0 = map.z0;
  const shopWin = new THREE.MeshLambertMaterial({ map: shopWindowTexture() });
  const dark = new THREE.MeshLambertMaterial({ color: "#2a2d30" });
  const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), up = new THREE.Vector3(0, 1, 0), one = new THREE.Vector3(1, 1, 1);
  for (const [x, y, z, ang, width, name, style] of D.sh ?? []) {
    const w = width as number, g = (z as number) - Z0;
    const frame = new THREE.Group();
    q.setFromAxisAngle(up, ang as number);
    frame.applyMatrix4(m4.compose(new THREE.Vector3(x as number, g, -(y as number)), q, one));
    const face = new THREE.MeshLambertMaterial({ map: fasciaTexture(name as string, style as string, 1024, Math.round(1024 * 0.62 / w)) });
    const fascia = new THREE.Mesh(new THREE.BoxGeometry(w, 0.62, 0.14), [dark, dark, dark, dark, face, dark]);
    fascia.position.set(0, 3.05, 0.07);
    frame.add(fascia);
    if (style !== "pub") {
      const win = new THREE.Mesh(new THREE.BoxGeometry(w - 0.5, 2.25, 0.06), [dark, dark, dark, dark, shopWin, dark]);
      win.position.set(0, 1.55, 0.03);
      frame.add(win);
    } else {
      // hanging sign on an iron bracket at one end of the fascia
      const arm = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.05, 1.1), dark);
      arm.position.set(w / 2 - 0.3, 3.75, 0.55);
      const board = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.95, 0.8),
        [face, face, dark, dark, dark, dark]);
      board.position.set(w / 2 - 0.3, 3.2, 0.7);
      frame.add(arm, board);
    }
    frame.traverse((o) => { (o as THREE.Mesh).castShadow = true; });
    scene.add(frame);
    culler.add(frame, 160);
  }
}
